parameters.text:
=You are a professional mobile accessories inventory manager AI. Help store staff manage products, stock, sales, transactions, low-stock alerts and reports. Always answer using real inventory data from the connected database. Never invent stock quantities, prices, products, SKUs, suppliers or transactions. Before changing inventory: find the product, verify the SKU/name, check current stock, apply the change, prevent negative stock, and record the transaction. Use PKR currency unless the user chooses another. Keep responses concise and professional. Return ONLY a JSON object with two keys: 'operation' (one of: search, add, stock_in, stock_out, report, low_stock) and 'parameters' (an object with keys such as sku, product_name, product, name, category, brand, quantity, selling_price, cost_price, current_stock, reorder_level, supplier, notes, customer). Do not add any text outside the JSON.

Here is the raw request payload received from the webhook. Identify the user's request from it and produce the JSON intent exactly as specified above:
{{ JSON.stringify($json.body || $json) }}

parameters.jsCode:
const raw = $input.first().json;

let text = '';
let op = raw.operation;
let p = raw.parameters || raw;

if (!op) {
  text = raw.output || raw.text || raw.message || '';

  if (!text && raw.response) text = raw.response;
  if (!text && raw.result) text = raw.result;

  text = String(text)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  let parsed = null;

  try {
    parsed = JSON.parse(text);
  } catch (e) {
    const m = text.match(/\{[\s\S]*\}/);
    if (m) {
      try {
        parsed = JSON.parse(m[0]);
      } catch (e2) {
        parsed = null;
      }
    }
  }

  if (parsed && typeof parsed === 'object') {
    op = parsed.operation || parsed.action || '';
    p = parsed.parameters || parsed.data || parsed;
  } else {
    op = '';
    p = {};
  }
}

op = String(op || '')
  .toLowerCase()
  .replace(/[_-]/g, ' ')
  .trim();

const originalOp = op;

const map = {
  add: 'add',
  create: 'add',
  update: 'add',
  edit: 'add',
  insert: 'add',
  upsert: 'add',
  'new product': 'add',
  product: 'add',

  'stock in': 'stock_in',
  receive: 'stock_in',
  received: 'stock_in',
  restock: 'stock_in',
  purchase: 'stock_in',
  bought: 'stock_in',
  incoming: 'stock_in',

  'stock out': 'stock_out',
  sell: 'stock_out',
  sale: 'stock_out',
  sales: 'stock_out',
  sold: 'stock_out',
  remove: 'stock_out',
  outgoing: 'stock_out',

  report: 'report',
  summary: 'report',
  overview: 'report',
  stats: 'report',
  statistics: 'report',
  dashboard: 'report',
  'inventory report': 'report',

  'low stock': 'low_stock',
  'out of stock': 'low_stock',
  'out-of-stock': 'low_stock',
  reorder: 'low_stock',
  alerts: 'low_stock',
  'stock alerts': 'low_stock',

  search: 'search',
  find: 'search',
  show: 'search',
  list: 'search',
  lookup: 'search',
  get: 'search',
  view: 'search',
  display: 'search',
  check: 'search'
};

if (map[op]) {
  op = map[op];
} else if (!['add', 'stock_in', 'stock_out', 'report', 'low_stock', 'search'].includes(op)) {
  const searchText = `${text} ${JSON.stringify(p)}`.toLowerCase();

  if (/transaction history|recent transactions|recent sales|sales history|stock history|stock movement|stock movements|movement history|stock transactions|show transactions|list transactions|transaction report|transaction log|recent activity|show sales|sales report/.test(searchText)) {
    op = 'report';
  } else if (/low stock|reorder|out[- ]of[- ]stock|stock alert/.test(searchText)) {
    op = 'low_stock';
  } else if (/stock in|receive|received|restock|purchase|bought|incoming/.test(searchText)) {
    op = 'stock_in';
  } else if (/sell|sale|sales|sold|stock out|remove|outgoing/.test(searchText)) {
    op = 'stock_out';
  } else if (/report|summary|overview|stats|statistics|dashboard|inventory value|today/.test(searchText)) {
    op = 'report';
  } else if (/add|create|new product|insert|update product/.test(searchText)) {
    op = 'add';
  } else {
    op = 'search';
  }
}

const num = (value, fallback = -1) => {
  if (value === undefined || value === null || value === '') return fallback;

  const n = Number(
    String(value)
      .replace(/,/g, '')
      .replace(/pkr|rs\.?/gi, '')
      .trim()
  );

  return Number.isFinite(n) ? n : fallback;
};

const integer = (value, fallback = 0) => {
  const n = parseInt(String(value ?? '').replace(/,/g, ''), 10);
  return Number.isFinite(n) ? n : fallback;
};

const str = (value, fallback = '') => {
  if (value === undefined || value === null) return fallback;
  return String(value).trim();
};

let userMsg = '';

try {
  userMsg =
    $node['Chat Input'].json.body?.chatInput ||
    $node['Chat Input'].json.body?.message ||
    $node['Chat Input'].json.chatInput ||
    $node['Chat Input'].json.message ||
    '';
} catch (e) {
  userMsg = '';
}

const combinedText = `${originalOp} ${text} ${userMsg}`.toLowerCase();

// Detect special report subtype
let reportType = '';

const reportTypeRegex = {
  transactions:
    /transaction history|recent transactions|recent sales|sales history|stock history|stock movement|stock movements|movement history|stock transactions|show transactions|list transactions|transaction report|transaction log|recent activity|show sales|sales report/i,
  low_stock: /low stock|reorder|stock alert/i,
  inventory: /inventory report|inventory summary|inventory overview/i
};

if (reportTypeRegex.transactions.test(combinedText)) {
  reportType = 'transactions';
} else if (reportTypeRegex.low_stock.test(combinedText)) {
  reportType = 'low_stock';
} else if (reportTypeRegex.inventory.test(combinedText)) {
  reportType = 'inventory';
}

// Route query-only intents by report subtype.
// A history/query request must NEVER be misinterpreted as a stock mutation.
const mutationOps = new Set(['add', 'stock_in', 'stock_out']);
if (reportType === 'transactions' && !mutationOps.has(originalOp)) {
  op = 'report';
}
if (reportType === 'low_stock' && !mutationOps.has(originalOp)) {
  op = 'low_stock';
}
if (reportType === 'inventory' && !mutationOps.has(originalOp)) {
  op = 'report';
}

const transactionType =
  op === 'stock_out'
    ? (/sell|sale|sales|sold/i.test(combinedText) ? 'SALE' : 'STOCK_OUT')
    : op === 'stock_in'
      ? 'STOCK_IN'
      : '';

const quantity = integer(p.quantity, 0);

const currentStockValue = num(p.current_stock, -1);

const currentStock =
  currentStockValue >= 0
    ? currentStockValue
    : -1;

const reorderLevel = num(p.reorder_level, -1);

const result = {
  operation: op,
  report_type: reportType,
  transaction_type: transactionType,

  sku: str(p.sku || p.product_sku || p.code),
  product_name: str(p.product_name || p.product || p.name || p.title),

  category: str(p.category),
  brand: str(p.brand),
  compatibility: str(p.compatibility),
  color: str(p.color || p.colour),

  quantity,

  cost_price: num(p.cost_price, -1),
  selling_price: num(p.selling_price, -1),

  current_stock: currentStock,
  reorder_level: reorderLevel,

  supplier: str(p.supplier || p.supplier_name),
  location: str(p.location || p.storage_location),

  supplier_customer: str(
    p.supplier_customer ||
    p.customer ||
    p.customer_name ||
    p.supplier
  ),

  notes: str(p.notes || p.note || p.description)
};

result.validation = {
  has_product_identifier: Boolean(result.sku || result.product_name),
  has_quantity: result.quantity > 0,
  has_selling_price: result.selling_price >= 0,
  has_cost_price: result.cost_price >= 0,
  has_reorder_level: result.reorder_level >= 0
};

return [{ json: result }];

const items = $input.all();
const product = items.length ? items[0].json : null;
const ei = $node['Extract Intent'].json;

if (!product || !product.sku) {
  return [{
    json: {
      error: 'Product not found. Please verify the SKU or product name.'
    }
  }];
}

const qty = Number(ei.quantity || 0);

if (!Number.isInteger(qty) || qty <= 0) {
  return [{
    json: {
      error: 'Quantity must be a positive whole number.'
    }
  }];
}

const previousStock = Number(product.current_stock || 0);
const isStockOut = ei.operation === 'stock_out';

if (isStockOut && qty > previousStock) {
  return [{
    json: {
      error:
        `Insufficient stock. ${product.product_name} (${product.sku}) has only ` +
        `${previousStock} units available, but ${qty} were requested.`
    }
  }];
}

const newStock = isStockOut
  ? previousStock - qty
  : previousStock + qty;

const transactionType = isStockOut
  ? (ei.transaction_type === 'SALE' ? 'SALE' : 'STOCK_OUT')
  : 'STOCK_IN';

const unitPrice = isStockOut
  ? Number(product.selling_price || 0)
  : Number(product.cost_price || product.selling_price || 0);

const totalAmount = unitPrice * qty;

const now = new Date();
const pad2 = (n) => String(n).padStart(2, '0');
const transactionId =
  'TXN-' +
  now.getFullYear() +
  pad2(now.getMonth() + 1) +
  pad2(now.getDate()) +
  '-' +
  Math.random().toString(36).slice(2, 8).toUpperCase();

let notes = ei.notes || '';

if (!notes) {
  notes = transactionType === 'SALE'
    ? 'Customer sale'
    : transactionType === 'STOCK_IN'
      ? 'Stock received'
      : 'Stock adjustment';
}

return [{
  json: {
    sku: product.sku,
    product_name: product.product_name,

    quantity: qty,

    previous_stock: previousStock,
    new_stock: newStock,

    transaction_type: transactionType,

    unit_price: unitPrice,
    total_amount: totalAmount,

    supplier_customer: ei.supplier_customer || '',
    notes,

    transaction_id: transactionId,

    status_after_transaction:
      newStock <= 0
        ? 'OUT_OF_STOCK'
        : newStock <= Number(product.reorder_level || 0)
          ? 'LOW_STOCK'
          : 'IN_STOCK'
  }
}];

const items = $input.all();
let totalProducts = 0, totalUnits = 0, totalValue = 0, totalCost = 0, lowStock = 0, outOfStock = 0;
for (const it of items) {
  const p = it.json;
  totalProducts += 1;
  const stock = Number(p.current_stock || 0);
  totalUnits += stock;
  totalValue += stock * (Number(p.selling_price || 0));
  totalCost += stock * (Number(p.cost_price || 0));
  if (stock <= Number(p.reorder_level || 0)) lowStock += 1;
  if (stock === 0) outOfStock += 1;
}
const potentialGrossMargin = totalValue - totalCost;
return [{ json: { inventory_summary: {
  report_type: 'inventory',
  products: totalProducts,
  units: totalUnits,
  inventory_value: totalValue,
  inventory_cost: totalCost,
  potential_gross_margin: potentialGrossMargin,
  low_stock: lowStock,
  out_of_stock: outOfStock
} } }];

const items = $input.all();
const ei = $node['Extract Intent'].json;

const esc = (v) => String(v ?? '');

const out = {
  success: true,
  operation: ei.operation,
  timestamp: new Date().toISOString()
};

const alerts = [];

const responseLine = (p) =>
  esc(p.sku) + ' | ' + esc(p.product_name) + ' | Stock: ' + esc(p.current_stock) +
  ' | Price: ' + esc(p.selling_price) + ' PKR | Status: ' + esc(p.status);

const money = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n.toLocaleString('en-PK') : '0';
};

let text = '';
let type = 'info';

// 1. Stock transaction result
try {
  const op = $node['Stock Operation Processor'].json;
  if (op && op.sku && !items.some(i => i.json.error)) {
    type = 'transaction';
    out.type = 'transaction';
    out.transaction = {
      id: op.transaction_id,
      type: op.transaction_type,
      product: op.product_name,
      sku: op.sku,
      quantity: op.quantity,
      previous_stock: op.previous_stock,
      new_stock: op.new_stock,
      unit_price: op.unit_price,
      total_amount: op.total_amount,
      status: op.status_after_transaction,
      party: op.supplier_customer || '',
      notes: op.notes || ''
    };
    out.message = op.transaction_type === 'SALE'
      ? 'Sale completed successfully.'
      : op.transaction_type === 'STOCK_IN'
        ? 'Stock received successfully.'
        : 'Stock updated successfully.';
    out.data = out.transaction;
    const sign = (op.transaction_type === 'SALE' || op.transaction_type === 'STOCK_OUT') ? '-' : '+';
    text = 'SUCCESS\nOperation: ' + op.transaction_type + '\nProduct: ' + op.product_name + ' (' + op.sku + ')\nQuantity: ' + sign + op.quantity;
    if (op.previous_stock !== null && op.previous_stock !== undefined) text += '\nPrevious stock: ' + op.previous_stock;
    if (op.new_stock !== null && op.new_stock !== undefined) text += '\nNew stock: ' + op.new_stock;
    if (op.total_amount) text += '\nTotal: ' + money(op.total_amount) + ' PKR';
    if (op.status_after_transaction === 'LOW_STOCK') {
      alerts.push('Low stock alert: ' + op.product_name + ' has ' + op.new_stock + ' units remaining.');
    }
    if (op.status_after_transaction === 'OUT_OF_STOCK') {
      alerts.push('Out of stock: ' + op.product_name + ' needs immediate restocking.');
    }
  }
} catch (e) {}

// 2. Add / update product
if (!text) {
  try {
    const product = $node['Add Product DB'].json;
    if (product && product.sku) {
      type = 'product';
      out.type = 'product';
      out.product = {
        sku: product.sku,
        product_name: product.product_name,
        selling_price: product.selling_price,
        current_stock: product.current_stock,
        status: product.status
      };
      out.message = 'Product ' + product.product_name + ' (' + product.sku + ') was added or updated successfully.';
      out.data = out.product;
      text = 'SUCCESS\nOperation: ADD / UPDATE PRODUCT\nProduct: ' + product.product_name + ' (' + product.sku + ')';
      if (product.current_stock !== null && product.current_stock !== undefined) text += '\nCurrent stock: ' + product.current_stock;
      text += '\nSelling price: ' + product.selling_price + ' PKR\nStatus: ' + product.status;
    }
  } catch (e) {}
}

// 3. Transaction history
if (!text) {
  const txnItem = items.find(i => i.json.transaction_history);
  if (txnItem) {
    const rows = txnItem.json.transaction_history || [];
    type = 'transactions';
    out.type = 'transactions';
    out.report_type = 'transactions';
    out.message = rows.length ? rows.length + ' recent transaction(s) found.' : 'No transactions recorded yet.';
    out.data = rows;
    if (!rows.length) {
      text = 'No transactions recorded yet.';
    } else {
      text = 'RECENT TRANSACTIONS';
      for (const t of rows) {
        text += '\n\n' + t.transaction_id + '\n';
        text += t.transaction_type + '\n';
        text += (t.product_name ? t.product_name : '') + (t.sku ? ' (' + t.sku + ')' : '') + '\n';
        text += 'Quantity: ' + t.quantity + '\n';
        if (t.previous_stock !== null && t.previous_stock !== undefined) text += 'Previous stock: ' + t.previous_stock + '\n';
        if (t.new_stock !== null && t.new_stock !== undefined) text += 'New stock: ' + t.new_stock + '\n';
        if (t.unit_price) text += 'Unit price: ' + money(t.unit_price) + ' PKR\n';
        if (t.total_amount) text += 'Total: ' + money(t.total_amount) + ' PKR\n';
        if (t.supplier_customer) text += 'Party: ' + t.supplier_customer + '\n';
        const dt = new Date(t.timestamp);
        if (!isNaN(dt.getTime())) {
          text += 'Date: ' + dt.toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' });
        }
      }
      text = text.trim();
    }
  }
}

// 4. Low stock report
if (!text) {
  const lsItem = items.find(i => i.json.low_stock_report);
  if (lsItem) {
    const rows = lsItem.json.low_stock_report || [];
    type = 'low_stock';
    out.type = 'low_stock';
    out.report_type = 'low_stock';
    out.message = rows.length ? rows.length + ' low stock product(s).' : 'All products are sufficiently stocked.';
    out.data = rows;
    for (const r of rows) {
      if (String(r.status || '').toUpperCase() === 'OUT_OF_STOCK' || Number(r.current_stock) === 0) {
        alerts.push(r.product_name + ' (' + r.sku + ') is out of stock.');
      } else {
        alerts.push(r.product_name + ' (' + r.sku + ') is low on stock.');
      }
    }
    if (!rows.length) {
      text = 'No low-stock products. All stock levels are healthy.';
    } else {
      text = 'LOW STOCK REPORT';
      for (const r of rows) {
        text += '\n\n' + responseLine(r);
        text += '\nReorder level: ' + r.reorder_level + ' | Suggested reorder: ' + r.suggested_reorder_qty;
      }
      text = text.trim();
    }
  }
}

// 5. Inventory report
if (!text) {
  const summaryItem = items.find(i => i.json.inventory_summary);
  if (summaryItem) {
    const s = summaryItem.json.inventory_summary;
    type = 'report';
    out.type = 'report';
    out.report_type = 'inventory';
    out.summary = {
      total_products: s.products,
      total_units: s.units,
      inventory_value: s.inventory_value,
      inventory_cost: s.inventory_cost,
      potential_gross_margin: s.potential_gross_margin,
      low_stock_items: s.low_stock,
      out_of_stock_items: s.out_of_stock
    };
    out.message = 'Inventory report generated successfully.';
    out.data = out.summary;
    text = 'INVENTORY SUMMARY\nProducts: ' + s.products + '\nTotal units: ' + s.units;
    text += '\nInventory cost: ' + s.inventory_cost + ' PKR\nInventory value: ' + s.inventory_value + ' PKR';
    if (s.potential_gross_margin !== undefined) text += '\nPotential gross margin: ' + s.potential_gross_margin + ' PKR';
    text += '\nLow stock: ' + s.low_stock + '\nOut of stock: ' + s.out_of_stock;
  }
}

// 6. Products / search
if (!text) {
  const products = items
    .map(i => i.json)
    .filter(p => p.sku && !p.error && !p.transaction_history && !p.low_stock_report && !p.inventory_summary);
  if (products.length) {
    type = 'products';
    out.type = 'products';
    out.products = products.map(p => ({
      sku: p.sku,
      product_name: p.product_name,
      category: p.category || '',
      brand: p.brand || '',
      compatibility: p.compatibility || '',
      color: p.color || '',
      selling_price: p.selling_price,
      current_stock: p.current_stock,
      reorder_level: p.reorder_level,
      status: p.status
    }));
    out.count = products.length;
    out.message = products.length === 1 ? 'Product found.' : products.length + ' products found.';
    out.data = out.products;
    text = (products.length === 1 ? 'PRODUCT\n' : 'PRODUCTS (' + products.length + ')\n');
    for (const p of products) {
      text += responseLine(p) + '\n';
    }
    text = text.trim();
  }
}

// 7. Error
if (!text) {
  const err = items.find(i => i.json.error);
  if (err) {
    out.success = false;
    out.operation = ei.operation;
    out.error = err.json.error;
    text = 'ERROR:\n' + err.json.error + '\nRequired info:\n- Verify the product SKU or name.\n- Provide a valid quantity and required fields.';
  }
}

// 8. Empty
if (!text) {
  out.success = false;
  out.message = 'No results found.';
  out.hint = 'Try "Search iPhone cover", "Show all products", "Show recent transactions" or "Show low stock products".';
  text = 'No results found. Try "Search iPhone cover" or "Show all products".';
}

out.response = text.trim();
out.alerts = alerts;
out.text = out.response;

return [{ json: out }];

const items = $input.all();
const rows = [];
for (const it of items) {
  const p = it.json;
  if (!p.transaction_id && !p.sku) continue;
  rows.push({
    transaction_id: p.transaction_id,
    sku: p.sku,
    product_name: p.product_name,
    transaction_type: p.transaction_type,
    quantity: p.quantity,
    previous_stock: p.previous_stock,
    new_stock: p.new_stock,
    unit_price: p.unit_price,
    total_amount: p.total_amount,
    supplier_customer: p.supplier_customer || '',
    notes: p.notes || '',
    timestamp: p.timestamp || p.created_at || ''
  });
}
return [{ json: { transaction_history: rows } }];

const items = $input.all();
const rows = [];
for (const it of items) {
  const p = it.json;
  if (!p.sku) continue;
  const currentStock = Number(p.current_stock || 0);
  const reorderLevel = Number(p.reorder_level || 0);
  rows.push({
    sku: p.sku,
    product_name: p.product_name,
    category: p.category || '',
    current_stock: currentStock,
    reorder_level: reorderLevel,
    selling_price: p.selling_price,
    status: p.status || 'LOW_STOCK',
    suggested_reorder_qty: Math.max(reorderLevel * 2 - currentStock, 0)
  });
}
return [{ json: { low_stock_report: rows } }];
